package com.cyancoder.media.service;import com.cyancoder.media.model.*;import com.cyancoder.media.repository.*;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class MediaReferenceService{private final MediaReferenceRepository references;private final MediaUploadRepository uploads;public MediaReferenceService(MediaReferenceRepository r,MediaUploadRepository u){references=r;uploads=u;}@Transactional public Map<String,Object> register(String tenant,String site,String asset,ReferenceRequest request){uploads.findByAssetKeyAndTenantKeyAndSiteKey(asset,tenant,blank(site)).orElseThrow(()->new IllegalArgumentException("Asset not found"));MediaReferenceEntity e=references.findByTenantKeyAndSiteKeyAndAssetKeyAndOwnerServiceAndOwnerTypeAndOwnerKeyAndFieldPath(tenant,blank(site),asset,request.ownerService(),request.ownerType(),request.ownerKey(),request.fieldPath()).orElseGet(MediaReferenceEntity::new);if(e.getReferenceId()==null){e.setReferenceId(UUID.randomUUID().toString());e.setTenantKey(tenant);e.setSiteKey(blank(site));e.setAssetKey(asset);e.setOwnerService(request.ownerService());e.setOwnerType(request.ownerType());e.setOwnerKey(request.ownerKey());e.setFieldPath(request.fieldPath());e.setCreatedAt(Instant.now());references.save(e);}return map(e);}@Transactional public void unregister(String tenant,String site,String asset,ReferenceRequest request){references.findByTenantKeyAndSiteKeyAndAssetKeyAndOwnerServiceAndOwnerTypeAndOwnerKeyAndFieldPath(tenant,blank(site),asset,request.ownerService(),request.ownerType(),request.ownerKey(),request.fieldPath()).ifPresent(references::delete);}public List<Map<String,Object>> list(String tenant,String site,String asset){return references.findByTenantKeyAndSiteKeyAndAssetKeyOrderByCreatedAtAsc(tenant,blank(site),asset).stream().map(this::map).toList();}private Map<String,Object>map(MediaReferenceEntity e){return Map.of("referenceId",e.getReferenceId(),"ownerService",e.getOwnerService(),"ownerType",e.getOwnerType(),"ownerKey",e.getOwnerKey(),"fieldPath",e.getFieldPath(),"createdAt",e.getCreatedAt().toString());}private String blank(String v){return v==null||v.isBlank()?null:v;}public record ReferenceRequest(String ownerService,String ownerType,String ownerKey,String fieldPath){public ReferenceRequest{if(ownerService==null||ownerService.isBlank()||ownerType==null||ownerType.isBlank()||ownerKey==null||ownerKey.isBlank()||fieldPath==null||fieldPath.isBlank())throw new IllegalArgumentException("Reference owner fields are required");}}}
